package com.bank.priority.task;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Time-sensitive work: settle a trade for a customer.
public class SettlementTask implements Runnable {
    private static final Logger log = Logger.getLogger(SettlementTask.class.getName());
    private final String tradeId;
    private final AtomicLong counter;

    public SettlementTask(String tradeId, AtomicLong counter) {
        this.tradeId = tradeId;
        this.counter = counter;
    }

    @Override
    public void run() {
        // Simulate a small, fast settlement for Rajesh (SAV2001).
        BigDecimal amount = new BigDecimal("50000");
        long iterations = 0;
        long end = System.nanoTime() + 2_000_000L; // ~2ms of CPU work
        while (System.nanoTime() < end) iterations++;
        counter.incrementAndGet();
        log.fine(() -> "Settled " + tradeId + " amount " + amount
                + " on " + Thread.currentThread().getName()
                + " priority=" + Thread.currentThread().getPriority());
    }
}
