package com.bank.priority.runner;

import com.bank.priority.task.ReconciliationTask;
import com.bank.priority.task.SettlementTask;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Runs the two workloads two ways: the naive priority approach and the
// correct dedicated-pool approach. Shows priority is not a reliable control.
public class WorkloadRunner {
    private static final Logger log = Logger.getLogger(WorkloadRunner.class.getName());

    // NAIVE: one shared pool, differentiate only by thread priority.
    public long[] runWithPriorityHint(int settlements, int recons) throws InterruptedException {
        AtomicLong settled = new AtomicLong();
        AtomicLong reconciled = new AtomicLong();
        ExecutorService shared = Executors.newFixedThreadPool(4, r -> {
            Thread t = new Thread(r, "shared-pool-thread");
            return t;
        });

        for (int i = 0; i < recons; i++) {
            final long id = i;
            shared.execute(() -> {
                Thread.currentThread().setPriority(Thread.MIN_PRIORITY); // "please run last"
                new ReconciliationTask(id, reconciled).run();
            });
        }
        for (int i = 0; i < settlements; i++) {
            final String id = "TRD-" + i;
            shared.execute(() -> {
                Thread.currentThread().setPriority(Thread.MAX_PRIORITY); // "please run first"
                new SettlementTask(id, settled).run();
            });
        }
        shared.shutdown();
        shared.awaitTermination(30, TimeUnit.SECONDS);
        log.info(() -> "NAIVE priority approach -> settled=" + settled.get()
                + " reconciled=" + reconciled.get()
                + " (priority did NOT guarantee ordering)");
        return new long[]{settled.get(), reconciled.get()};
    }

    // CORRECT: separate pools enforce the resource split in code.
    public long[] runWithDedicatedPools(int settlements, int recons) throws InterruptedException {
        AtomicLong settled = new AtomicLong();
        AtomicLong reconciled = new AtomicLong();
        ExecutorService settlePool = Executors.newFixedThreadPool(10,
                named("settlement-pool"));
        ThreadPoolExecutor reconPool = new ThreadPoolExecutor(
                2, 2, 0L, TimeUnit.MILLISECONDS,
                new ArrayBlockingQueue<>(500), named("reconciliation-pool"),
                new ThreadPoolExecutor.CallerRunsPolicy());

        for (int i = 0; i < settlements; i++)
            settlePool.execute(new SettlementTask("TRD-" + i, settled));
        for (int i = 0; i < recons; i++)
            reconPool.execute(new ReconciliationTask(i, reconciled));

        settlePool.shutdown();
        reconPool.shutdown();
        settlePool.awaitTermination(30, TimeUnit.SECONDS);
        reconPool.awaitTermination(30, TimeUnit.SECONDS);
        log.info(() -> "CORRECT dedicated-pool approach -> settled=" + settled.get()
                + " reconciled=" + reconciled.get()
                + " (capacity enforced by the application)");
        return new long[]{settled.get(), reconciled.get()};
    }

    private ThreadFactory named(String prefix) {
        return new ThreadFactory() {
            private int n = 1;
            public synchronized Thread newThread(Runnable r) {
                return new Thread(r, prefix + "-thread-" + n++);
            }
        };
    }
}
