package com.bank.priority;

import com.bank.priority.runner.WorkloadRunner;

import java.util.logging.*;

// Runnable demo: show range, inheritance, the exception, then naive vs correct.
public class PriorityDemo {
    private static final Logger log = Logger.getLogger(PriorityDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PriorityLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        log.info(() -> "MIN=" + Thread.MIN_PRIORITY
                + " NORM=" + Thread.NORM_PRIORITY
                + " MAX=" + Thread.MAX_PRIORITY);

        // Inheritance: the child inherits the caller's priority, not always 5.
        Thread.currentThread().setPriority(7);
        Thread child = new Thread(() -> {}, "child");
        log.info(() -> "child inherited priority=" + child.getPriority()
                + " (equals caller's 7, NOT default 5)");
        Thread.currentThread().setPriority(Thread.NORM_PRIORITY);

        // Out-of-range throws IllegalArgumentException.
        try {
            new Thread().setPriority(11);
        } catch (IllegalArgumentException e) {
            log.warning("setPriority(11) rejected: " + e.getMessage());
        }

        WorkloadRunner runner = new WorkloadRunner();
        runner.runWithPriorityHint(200, 200);
        runner.runWithDedicatedPools(200, 200);
    }
}

// ─── Would be in PriorityLogFormatter.java in a real project ───
class PriorityLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
