package com.bank.priority;

import com.bank.priority.runner.WorkloadRunner;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ThreadPriorityTest {

    @Test
    void rangeConstantsAreOneToTen() {
        assertEquals(1, Thread.MIN_PRIORITY);
        assertEquals(5, Thread.NORM_PRIORITY);
        assertEquals(10, Thread.MAX_PRIORITY);
    }

    @Test
    void outOfRangePriorityThrows() {
        Thread t = new Thread();
        assertThrows(IllegalArgumentException.class, () -> t.setPriority(0));
        assertThrows(IllegalArgumentException.class, () -> t.setPriority(11));
    }

    @Test
    void childInheritsCallerPriorityNotDefault() throws InterruptedException {
        Thread.currentThread().setPriority(8);
        try {
            Thread child = new Thread(() -> {});
            assertEquals(8, child.getPriority(), "child must inherit caller's priority");
        } finally {
            Thread.currentThread().setPriority(Thread.NORM_PRIORITY);
        }
    }

    @Test
    void bothApproachesCompleteAllWork() throws InterruptedException {
        WorkloadRunner runner = new WorkloadRunner();
        long[] naive = runner.runWithPriorityHint(50, 50);
        long[] correct = runner.runWithDedicatedPools(50, 50);
        // Priority does not change CORRECTNESS: all work still completes.
        assertEquals(50, naive[0]);
        assertEquals(50, naive[1]);
        assertEquals(50, correct[0]);
        assertEquals(50, correct[1]);
    }
}
